// Generated by scaffold-page-from-story from user_stories/A-01-signin.yaml
// Story: US-A-01-SIGNIN
// Role:  all
// Feature: Email and password sign-in
// Goal: As a registered user I can sign in with my email and password so that my cart, orders and courses are mine again.
//
// Restyled by convert-pages to mirror design/html/student/A-01-signin.html.
// Scope-locked parts preserved verbatim: every data-testid, the default export
// (SignInPage), and the data wiring (POST /api/auth/login + GET /api/auth/me
// fetch calls with their loading/error/empty branches).

import { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useAppDispatch } from '~/hooks/useAppDispatch';
import { loginThunk, fetchMeThunk } from '~/services/httpServices/authService';
import { toast } from '~/lib/toast';
import { getApiErrorMessage } from '~/utils/apiError';
import { FieldError, fieldProps } from '~/components/shared/FieldError';
import { email as emailRule, readForm, required, serverFieldErrors, validate, type FieldErrors } from '~/utils/validation';
import { ArrowLeft } from 'lucide-react';

export default function SignInPage() {
  const { t } = useTranslation('common');
  const navigate = useNavigate();
  const dispatch = useAppDispatch();

  const [data2, setData2] = useState<unknown>(null);
  const [loading2, setLoading2] = useState<boolean>(true);
  const [error2, setError2] = useState<string | null>(null);

  // Existing-session probe — GET /api/auth/me via the auth read thunk; surfaces
  // the KPI card only when a session already exists (guests reject silently).
  useEffect(() => {
    let cancelled = false;
    setLoading2(true);
    setError2(null);
    dispatch(fetchMeThunk()).unwrap()
      .then((d) => { if (!cancelled) setData2(d); })
      .catch((e: unknown) => { if (!cancelled) setError2(e instanceof Error ? e.message : 'Not signed in'); })
      .finally(() => { if (!cancelled) setLoading2(false); });
    return () => { cancelled = true; };
  }, [dispatch]);

  const [loading1, setLoading1] = useState<boolean>(false);
  const [errors, setErrors] = useState<FieldErrors>({});

  const createLogin1 = async () => {
    // Check here first: a blank form does not need a round trip to be told it
    // is blank, and the person gets the answer next to the field instead of in
    // a toast that names one of them.
    const values = readForm(document.querySelector('[data-testid="a-01-signin-ac-1"]'));
    const found = validate(values, {
      email: [required(t('auth.email', 'Email')), emailRule()],
      password: [required(t('auth.password', 'Password'))],
    });
    setErrors(found);
    if (Object.keys(found).length) {
      const first = document.querySelector<HTMLElement>(`[name="${Object.keys(found)[0]}"]`);
      first?.focus();
      return;
    }
    setLoading1(true);
    const __body: Record<string, unknown> = {};
    if (typeof document !== 'undefined') {
      const __sect = document.querySelector('[data-testid="a-01-signin-ac-1"]');
      __sect?.querySelectorAll('input, textarea, select').forEach((el) => {
        const __el = el as HTMLInputElement; const n = __el.name; const v = __el.value;
        if (n && v) __body[n] = __el.type === 'number' ? Number(v) : v;
      });
    }
    try {
      const email = String(__body.email ?? '');
      const password = String(__body.password ?? '');
      await dispatch(loginThunk({ email, password })).unwrap();
      toast.success(t('auth.signedIn', 'Signed in'));
      navigate('/');
    } catch (err) {
      // The server marks fields too, when it can say which.
      setErrors(serverFieldErrors(err));
      toast.error(getApiErrorMessage(err, t('auth.signInFailed', 'Could not sign in')));
    } finally {
      setLoading1(false);
    }
  };

  const session = (data2 && typeof data2 === 'object') ? data2 as Record<string, unknown> : {};

  return (
    <div className="bg-[var(--c-canvas)]" data-testid="a-01-signin-page">
      <main
        data-shell="content"
        data-testid="a-01-signin-main"
        className="flex min-h-[70vh] items-center justify-center py-[64px] px-[24px]"
      >
        <div className="w-full max-w-[420px] space-y-[16px]">
          {/* single back-link (page content, not shared chrome) */}
          <Link
            to="/"
            data-testid="a-01-signin-home-link"
            className="inline-flex min-h-[36px] items-center gap-[4px] text-[14px] text-[var(--c-muted)] hover:text-[var(--c-primary)]"
          >
            <ArrowLeft className="w-4 h-4" aria-hidden="true" />
            {t('nav.home', 'Home')}
          </Link>

          <form
            className="rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[0_1px_3px_rgb(29_32_38/0.08)] space-y-[16px]"
            data-testid="a-01-signin-ac-1"
            onSubmit={(e) => { e.preventDefault(); createLogin1(); }}
          >
            <h1
              className="text-[24px] font-semibold leading-[1.25] tracking-[-0.2px] text-[var(--c-ink)]"
              data-testid="a-01-signin-heading"
            >
              {t('auth.welcomeBack', 'Welcome back')}
            </h1>

            <label className="flex flex-col gap-[4px]">
              <span className="text-[14px] font-medium text-[var(--c-ink)]">{t('auth.email', 'Email')}</span>
              <input
                name="email"
                type="email"
                placeholder={t('auth.emailPlaceholder', 'you@example.com')}
                data-testid="a-01-signin-ac-1-email"
                {...fieldProps('email', errors)}
                className="min-h-[44px] w-full rounded-[4px] border border-[var(--c-hairline-strong)] bg-[var(--c-canvas)] px-[12px] py-[8px] text-[15px] text-[var(--c-ink)] placeholder:text-[var(--c-muted)] focus:border-[var(--c-primary)] focus:outline focus:outline-2 focus:-outline-offset-1 focus:outline-[var(--c-primary)]"
              />
              <FieldError id="email-error" message={errors.email} />
            </label>

            <label className="flex flex-col gap-[4px]">
              <span className="text-[14px] font-medium text-[var(--c-ink)]">{t('auth.password', 'Password')}</span>
              <input
                name="password"
                type="password"
                placeholder={t('auth.passwordPlaceholder', 'Your password')}
                data-testid="a-01-signin-ac-1-password"
                {...fieldProps('password', errors)}
                className="min-h-[44px] w-full rounded-[4px] border border-[var(--c-hairline-strong)] bg-[var(--c-canvas)] px-[12px] py-[8px] text-[15px] text-[var(--c-ink)] placeholder:text-[var(--c-muted)] focus:border-[var(--c-primary)] focus:outline focus:outline-2 focus:-outline-offset-1 focus:outline-[var(--c-primary)]"
              />
              <FieldError id="password-error" message={errors.password} />
            </label>

            <button
              type="button"
              onClick={createLogin1}
              disabled={loading1}
              data-testid="a-01-signin-ac-1-action"
              className="inline-flex min-h-[48px] w-full cursor-pointer items-center justify-center gap-[8px] rounded-[6px] border border-transparent bg-[var(--c-primary)] px-[32px] py-[16px] text-[18px] font-semibold leading-[1] text-[var(--c-on-primary)] transition-colors hover:bg-[var(--c-primary-active)] disabled:cursor-not-allowed disabled:opacity-50"
            >
              {loading1 ? t('actions.loading', 'Loading...') : t('auth.signIn', 'Sign in')}
            </button>

            <p className="text-[14px] font-normal leading-[1.5] text-[var(--c-body)]" data-testid="a-01-signin-ac-3">
              {t('auth.noAccount', 'No account yet?')}{' '}
              <Link
                to="/signup"
                data-testid="a-01-signin-to-signup"
                className="text-[var(--c-link)] hover:underline"
              >
                {t('auth.createOne', 'Create one')}
              </Link>
            </p>
          </form>

          {/* session status — GET /api/auth/me; surfaces only when a session exists */}
          <div data-testid="a-01-signin-ac-2" className="text-center">
            {loading2 && (
              <p data-testid="a-01-signin-ac-2-loading" className="text-[12px] text-[var(--c-muted)]">
                {t('actions.loading', 'Loading...')}
              </p>
            )}
            {!loading2 && error2 && (
              <p data-testid="a-01-signin-ac-2-error" className="text-[12px] text-[var(--c-error)]">
                {t('auth.notSignedIn', '')}
              </p>
            )}
            {!loading2 && !error2 && data2 != null && (
              <div
                data-testid="a-01-signin-ac-2-kpis"
                className="grid grid-cols-1 gap-[16px] sm:grid-cols-3"
              >
                {Object.entries(session).slice(0, 6).map(([key, value]) => (
                  <div
                    key={key}
                    data-testid={`a-01-signin-ac-2-kpi-${key}`}
                    className="rounded-[8px] bg-[var(--c-surface-soft)] p-[12px]"
                  >
                    <p className="text-[12px] text-[var(--c-muted)]">{key}</p>
                    <p className="text-[24px] font-bold text-[var(--c-ink)]">
                      {typeof value === 'number' || typeof value === 'string' ? String(value) : '-'}
                    </p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}
